import pandas as pd

def clean(df):
    df = df.copy()
    # normalise species label variants (extra spaces)
    if 'species' in df.columns:
        df['species'] = df['species'].astype(str).str.strip()
    # normalise island label variants (case)
    if 'island' in df.columns:
        df['island'] = df['island'].astype(str).str.strip()
        # simple case normalisation to allowed capitalisation
        df['island'] = df['island'].str.capitalize()
    # body_mass_g is stored as text with commas / written as text
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = df['body_mass_g'].astype(str).str.replace(',', '', regex=False)
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    return df

def answer(df):
    dfc = clean(df)
    # average body mass per species, drop missing group keys
    means = dfc.groupby('species', dropna=False)['body_mass_g'].mean()
    # keep only allowed species and drop NaN groups
    result = {}
    for sp, val in means.items():
        if pd.isna(sp):
            continue
        if pd.isna(val):
            continue
        result[sp] = float(val)
    return result
